inline constexpr uint32_t kNearEthCount[kHarvestCases] = {91, 91, 91, 91, 96, 97, 98, 99, 98, 97, 91, 91, 91, 91};
inline constexpr uint8_t kRelayTo[kEthTiles] = {2, 3, 0, 1, 2, 3, 4, 5};   // the same-side tile each Ethernet tile hands relayed packets to

// compile-time re-checks of the bounds from the tables
constexpr bool check_all() {
    for (uint32_t h = 0; h < kHarvestCases; ++h) {
        uint32_t he = 99;
        for (uint32_t e = 0; e < kEthTiles; ++e) {
            const uint32_t a = du(kHub[h], kEth[e]), b = du(kEth[e], kHub[h]);
            const uint32_t m = a > b ? a : b;
            he = m < he ? m : he;
        }
        if (he > kNocHubEth) return false;
        if (du(kOwnerOrder[h][39], kHub[h]) > kUpOwn40 || du(kOwnerOrder[h][79], kHub[h]) > kUpOwn80 || du(kOwnerOrder[h][kCores - 2], kHub[h]) > kUpHops) return false;
        if (kNearEthCount[h] < kNearEthMin) return false;
        for (uint32_t r = 0; r < 2; ++r) {
            const Rect q = kHubMc[h][r];
            for (uint32_t i = 0; i < kCores - 1; ++i) {
                const Xy c = kOwnerOrder[h][i];
                if (c.x >= q.x0 && c.x <= q.x1 && c.y >= q.y0 && c.y <= q.y1 && (q.noc == 0 ? d0(kHub[h], c) : d1(kHub[h], c)) > kMcHops) return false;
            }
        }
    }
    for (uint32_t e = 0; e < kEthTiles; ++e) if (du(kEth[e], kEth[kRelayTo[e]]) > kNocEthEth) return false;
    return true;
}
static_assert(check_all(), "a hop bound of the stage model does not hold on the core map");

